insert into public.projects (slug, name, type, year, summary, intro, challenge, approach, outcome, scope, visual_theme, visual_note, sort_order) values ('nexora', 'Nexora', 'Digital product / Platform', '2025', 'A smarter way to bring complex business workflows into one clear workspace.', 'An ambitious platform concept shaped around the everyday decisions that move a business forward.', 'Fragmented tools can make essential work feel harder than it needs to be. The opportunity was to create a single, intuitive experience that brings the right information into focus.', 'We explored a modular product language with calm navigation, purposeful hierarchy, and dashboards designed around the tasks people return to most.', 'A clear product direction and flexible interface system ready for future workflows and deeper integrations.', 'Product strategy|UX design|Interface design|Frontend direction', 'sage', 'Concept presentation — imagery is illustrative.', 1)
