insert into public.projects (slug, name, type, year, summary, intro, challenge, approach, outcome, scope, visual_theme, visual_note, sort_order) values ('rowna', 'ROWNA', 'Commerce / Brand experience', '2025', 'An expressive commerce experience with editorial energy at every touchpoint.', 'A digital flagship designed to make discovery feel as compelling as the product itself.', 'An online store needs more than a catalog. It needs a point of view that helps people discover, trust, and remember the brand.', 'We built the experience around strong art direction, spacious product stories, and a direct path from inspiration to checkout.', 'A distinctive storefront direction with a scalable design language across campaigns and collections.', 'Art direction|eCommerce UX|Visual design|Responsive design', 'peach', 'Concept presentation — imagery is illustrative.', 2)
  on conflict (slug) do update set name = excluded.name, type = excluded.type, year = excluded.year, summary = excluded.summary, intro = excluded.intro, challenge = excluded.challenge, approach = excluded.approach, outcome = excluded.outcome, scope = excluded.scope, visual_theme = excluded.visual_theme, visual_note = excluded.visual_note, sort_order = excluded.sort_order;
insert into public.projects (slug, name, type, year, summary, intro, challenge, approach, outcome, scope, visual_theme, visual_note, sort_order) values ('hajj-umrah', 'Hajj & Umrah', 'Booking / Operations', '2025', 'A considered journey from first enquiry to confident travel planning.', 'A service platform that gives travellers clarity and teams better tools to support them.', 'Travel planning across packages, documents, dates, and support can quickly become overwhelming for both customers and operators.', 'We mapped the journey end to end and designed simple package discovery, booking states, and operational views for the team.', 'A practical blueprint for a calmer customer experience and a more connected management workflow.', 'Service design|Booking UX|Dashboard design|System architecture', 'sand', 'Concept presentation — imagery is illustrative.', 3)
  on conflict (slug) do update set name = excluded.name, type = excluded.type, year = excluded.year, summary = excluded.summary, intro = excluded.intro, challenge = excluded.challenge, approach = excluded.approach, outcome = excluded.outcome, scope = excluded.scope, visual_theme = excluded.visual_theme, visual_note = excluded.visual_note, sort_order = excluded.sort_order;
insert into public.projects (slug, name, type, year, summary, intro, challenge, approach, outcome, scope, visual_theme, visual_note, sort_order) values ('tomadachi', 'Tomadachi', 'Community / Experience', '2025', 'A playful digital home built around connection and discovery.', 'A community experience balancing personality, ease of use, and room to grow.', 'Community products need a sense of belonging while still making everyday actions effortless.', 'We developed a friendly visual system, clear discovery patterns, and flexible components for future features.', 'A warm, recognizable product direction designed for continued iteration.', 'Brand experience|Product design|Design system|Interaction design', 'lilac', 'Concept presentation — imagery is illustrative.', 4)
