insert into public.projects (slug, name, type, year, summary, intro, challenge, approach, outcome, scope, visual_theme, visual_note, sort_order) values ('school-management', 'School Management', 'Education / SaaS', '2025', 'Making the busy school day easier for administrators, teachers, and families.', 'One connected workspace for the people and processes behind better learning.', 'Schools coordinate information across many roles. Important details should be easy to find, update, and act on.', 'We organized the platform around role-specific tasks, useful status views, and a consistent interface for high-frequency work.', 'A structured product concept for managing school operations with greater clarity.', 'Workflow mapping|SaaS UX|Admin panels|UI design', 'blue', 'Concept presentation — imagery is illustrative.', 5)
