insert into public.projects (slug, name, type, year, summary, intro, challenge, approach, outcome, scope, visual_theme, visual_note, sort_order) values ('loomline', 'Loomline', 'Apparel manufacturing / ERP', '2026', 'One connected view from buyer order to cutting floor, stores and shipment.', 'An ERP concept for garment factories that need purchasing, production and stock to agree.', 'Orders, fabric stock and line capacity often live in separate sheets, so delays surface only when a shipment is already at risk.', 'We mapped order-to-shipment, modelled the bill of materials as a matrix, and designed role-based views for merchandisers, store keepers and line managers.', 'A clear operating blueprint that shows material needs, shortages and ship dates in one workspace.', 'Workflow mapping|ERP architecture|Dashboard design|Inventory logic', 'sage', 'Concept presentation — imagery is illustrative.', 6)
  on conflict (slug) do update set name = excluded.name, type = excluded.type, year = excluded.year, summary = excluded.summary, intro = excluded.intro, challenge = excluded.challenge, approach = excluded.approach, outcome = excluded.outcome, scope = excluded.scope, visual_theme = excluded.visual_theme, visual_note = excluded.visual_note, sort_order = excluded.sort_order;
insert into public.projects (slug, name, type, year, summary, intro, challenge, approach, outcome, scope, visual_theme, visual_note, sort_order) values ('carewell', 'Carewell', 'Healthcare / Booking', '2026', 'Appointments that fill the day without double bookings or phone tag.', 'A booking and patient-flow concept for clinics that want calmer front desks and shorter waits.', 'Clinics juggle walk-ins, follow-ups and doctor availability by phone and paper, so gaps and clashes are common.', 'We designed self-service booking, doctor schedules with clear states, and a front-desk view that makes today obvious at a glance.', 'A practical booking flow that reduces manual coordination and keeps the day moving.', 'Service design|Booking UX|Scheduling logic|Admin panels', 'blue', 'Concept presentation — imagery is illustrative.', 7)
  on conflict (slug) do update set name = excluded.name, type = excluded.type, year = excluded.year, summary = excluded.summary, intro = excluded.intro, challenge = excluded.challenge, approach = excluded.approach, outcome = excluded.outcome, scope = excluded.scope, visual_theme = excluded.visual_theme, visual_note = excluded.visual_note, sort_order = excluded.sort_order;
insert into public.projects (slug, name, type, year, summary, intro, challenge, approach, outcome, scope, visual_theme, visual_note, sort_order) values ('homestead', 'Homestead', 'Real estate / CRM', '2026', 'Every enquiry, viewing and follow-up in one pipeline the whole team can see.', 'A CRM concept for property teams where a missed call can mean a lost sale.', 'Leads arrive from portals, social media and phone calls, and nobody can say which ones are still warm.', 'We unified lead capture, assigned an owner to every enquiry and modelled the pipeline as a stage-by-stage forecast.', 'A shared pipeline with clear ownership, timely reminders and a forecast grounded in stage conversion.', 'CRM design|Pipeline modelling|Automation|Dashboard design', 'peach', 'Concept presentation — imagery is illustrative.', 8)
  on conflict (slug) do update set name = excluded.name, type = excluded.type, year = excluded.year, summary = excluded.summary, intro = excluded.intro, challenge = excluded.challenge, approach = excluded.approach, outcome = excluded.outcome, scope = excluded.scope, visual_theme = excluded.visual_theme, visual_note = excluded.visual_note, sort_order = excluded.sort_order;
insert into public.projects (slug, name, type, year, summary, intro, challenge, approach, outcome, scope, visual_theme, visual_note, sort_order) values ('routewise', 'Routewise', 'Logistics / Operations', '2026', 'Parcels, drivers and depots tracked on one calm operations board.', 'A dispatch and tracking concept for delivery teams working across several depots.', 'Dispatchers rely on calls and chat groups, so delays and failed deliveries are found late and customers keep asking where their parcel is.', 'We designed a live board of routes and statuses, proof-of-delivery steps and a customer tracking page that answers the question before it is asked.', 'A clear operations model that reduces status calls and makes exceptions visible early.', 'Operations design|Tracking UX|Dashboard design|Integrations', 'sand', 'Concept presentation — imagery is illustrative.', 9)
