insert into public.projects (slug, name, type, year, summary, intro, challenge, approach, outcome, scope, visual_theme, visual_note, sort_order) values ('tablesmart', 'Tablesmart', 'Hospitality / POS & stock', '2026', 'Orders, kitchen and stock room speaking the same language.', 'A point-of-sale and ingredient-stock concept for restaurants that hate running out of the best sellers.', 'Menus sell items that the kitchen has already run out of, and stock counts happen too late to prevent waste.', 'We linked each dish to its ingredients, so every order draws down stock and low items are flagged before service.', 'A connected ordering and stock flow that keeps the menu honest and cuts avoidable waste.', 'POS design|Inventory logic|Kitchen display UX|Reporting', 'lilac', 'Concept presentation — imagery is illustrative.', 10)
